head.script:
scwin.trigger1_onclick = function(e) {
    ngmf.popupExcelExport("gridView1", "dataList1", false, "");
};
scwin.test = function() {
    //alert("scwin.test");
    alertShowed = true;
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Script 탭에서 scwin.test = function() 부분을 확인한다.
    //1. In the Script tab, check scwin.test = function ().
    //Verify step 1. alert("scwin.test");
    //1. alert ("scwin.test");
    //Test step 2. gridView1.setDisabled 부분을 확인한다.
    //2. Check gridView1.setDisabled.
    //Verify step 2. gridView1.setDisabled("grid", true);
    //2. gridView1.setDisabled ("grid", true);
    //Test step 3. 브라우저에서 name2 컬럼의 셀에 이미지를 클릭한다.
    //3. In the browser, click the image in the cell of the name2 column.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').childNodes[0].click()");
    //Verify step 3. 아무런 반응이 없다. (전버전에서는 disabled 상태에서도 imageClickFunction이 실행되어 팝업이 생성되었음.)
    //3. There is no reaction. (In previous versions, imageClickFunction was executed even when disabled, resulting in a popup.)
    WebSquare.wUnit.addCommand("assert", "alertShowed", "false");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.alertShowed = false;
    //	dataList1.insertRow();
    gridView1.setDisabled("grid", true);
    //	gridView1.setCellDisabled( 0 , 1 , true );
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
